import { useContext } from 'react';
import { AuthContext } from '../../context/authContext';
import { DarkModeContext } from '../../context/darkModeContext';
import './messages.scss';

const Messages = () => {
  const { currentUser } = useContext(AuthContext);
  const { darkMode } = useContext(DarkModeContext);

  if (!currentUser) {
    return null;
  }

  // Mock messages data (replace with API)
  const messages = [
    { id: 1, sender: 'John Doe', content: 'Hey, how are you?', timestamp: '2025-04-20 10:00' },
    { id: 2, sender: 'Jane Doe', content: 'Let’s catch up!', timestamp: '2025-04-20 10:05' },
  ];

  return (
    <div className={`messages ${darkMode ? 'theme-dark' : 'theme-light'}`}>
      <h2>{currentUser.name}'s Messages</h2>
      <div className="message-list">
        {messages.map(message => (
          <div key={message.id} className="message-card">
            <div className="message-header">
              <span className="sender">{message.sender}</span>
              <span className="timestamp">{message.timestamp}</span>
            </div>
            <p>{message.content}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Messages;
